update public.guias set pdf_url = case slug when 'cultivar-calçots' then '/media/guias/cultivar-calcots.pdf' when 'plantar-boniatos' then '/media/guias/plantar-boniatos.pdf' when 'polinizacion-calabacines' then '/media/guias/polinizacion-calabacines.pdf' when 'poda-frutales' then '/media/guias/poda-frutales.pdf' end where slug in ('cultivar-calçots', 'plantar-boniatos', 'polinizacion-calabacines', 'poda-frutales') and nullif(trim(pdf_url), '') is null;